using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputEndpointProof {
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),common=File.ReadAllBytes(a[1]),after=File.ReadAllBytes(a[2]),ss=File.ReadAllBytes(a[3]),input=File.ReadAllBytes(a[4]),bounds=File.ReadAllBytes(a[5]);int sp=int.Parse(a[6]),stage=int.Parse(a[7]),count=BitConverter.ToInt16(ds,0x8792);var map=new int[count];var stems=new int[count];for(int i=1;i<count;i++){map[i]=BitConverter.ToInt16(common,0x2b5a+i*2);stems[i]=BitConverter.ToInt16(common,0x2a2e+i*2);}var rows=new List<float[]>();for(int i=0;i<BitConverter.ToInt16(ds,0x8798);i++){var p=new float[15];Buffer.BlockCopy(common,i*60,p,0,60);rows.Add(p);}int iterator=BitConverter.ToInt16(ds,BitConverter.ToUInt16(ss,sp+4+10*4));float first=BitConverter.ToSingle(input,2+iterator*4),last=BitConverter.ToSingle(input,6+iterator*4);var r=InputEndpointProjection.Decode(first,last,stage,rows,map,stems,BitConverter.ToSingle(bounds,8),BitConverter.ToSingle(bounds,4));short[] words={r.EndFlag,r.StartFlag,0,0,r.EndItem,r.StartItem,r.Number,r.EndNote,r.StartNote,r.Stem,(short)(iterator+1)};int checks=0;
 for(int i=0;i<11;i++){int offset=BitConverter.ToUInt16(ss,sp+4+i*4);if(i==2||i==3){float actual=i==2?r.EndPitch:r.StartPitch;uint bits=BitConverter.ToUInt32(BitConverter.GetBytes(actual),0);if(bits!=BitConverter.ToUInt32(after,offset))throw new Exception("Float argument "+(i+1));checks+=2;}else{if(words[i]!=BitConverter.ToInt16(after,offset))throw new Exception("Word argument "+(i+1)+": "+words[i]+" != "+BitConverter.ToInt16(after,offset));checks++;}}
 foreach(int offset in new[]{0x8108,0x8114}){float actual=offset==0x8108?r.StartX:r.EndX;if(BitConverter.ToUInt32(BitConverter.GetBytes(actual),0)!=BitConverter.ToUInt32(after,offset))throw new Exception("Coordinate "+offset.ToString("x4"));checks+=2;}Console.WriteLine("PASS "+checks+" original endpoint argument/coordinate words.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
